insert into public.places (id, city_id, category, zone, minutes, cost_kzt, title, location, address, summary, tip, map_query, source_url, has_photo, map_x, map_y, sort_order) values
  ('charyn', 'almaty', 'nature', 'daytrip', 540, 15000, '{"ru":"Чарынский каньон","kk":"Шарын шатқалы","en":"Charyn Canyon","ja":"チャリン・キャニオン"}'::jsonb, '{"ru":"Алматинская область","kk":"Алматы облысы","en":"Almaty Region","ja":"アルマトイ州"}'::jsonb, '{"ru":"Долина замков, Чарынский нацпарк","kk":"Қамалдар аңғары, Шарын ұлттық паркі","en":"Valley of Castles, Charyn National Park","ja":"チャリン国立公園・城の谷"}'::jsonb, '{"ru":"Тропа по Долине замков между рыжими скалами и открытыми смотровыми площадками.","kk":"Қызыл жартастар мен көрініс алаңдарының арасындағы Қамалдар аңғарының соқпағы.","en":"Follow the Valley of Castles trail past rust-red cliffs and open viewpoints.","ja":"赤い断崖と展望台を巡る「城の谷」のトレイル。"}'::jsonb, '{"ru":"Выделите день на дорогу и прогулку. Возьмите воду и скачайте карту заранее.","kk":"Жолға және серуенге бір күн бөліңіз. Су алып, картаны алдын ала жүктеңіз.","en":"Set aside a full day. Bring water and download a map before leaving.","ja":"移動を含めて丸一日を確保しましょう。水を持ち、事前に地図を保存してください。"}'::jsonb, 'Charyn Canyon Valley of Castles Kazakhstan', 'https://kazakhstan.travel/en/news/things-to-do-in-almaty-region', true, null, null, 0),
  ('kolsai', 'almaty', 'nature', 'daytrip', 600, 20000, '{"ru":"Кольсайские озёра","kk":"Көлсай көлдері","en":"Kolsai Lakes","ja":"コルサイ湖群"}'::jsonb, '{"ru":"Алматинская область","kk":"Алматы облысы","en":"Almaty Region","ja":"アルマトイ州"}'::jsonb, '{"ru":"Нижнее Кольсайское озеро, рядом с селом Саты","kk":"Төменгі Көлсай көлі, Саты ауылының маңы","en":"Lower Kolsai Lake, near Saty","ja":"サティ村近くの下コルサイ湖"}'::jsonb, '{"ru":"Горные озёра среди елей Тянь-Шаня. Начните с прогулки у нижнего озера.","kk":"Тянь-Шань шыршаларының арасындағы көлдер. Серуенді төменгі көлден бастаңыз.","en":"Mountain lakes among Tian Shan spruces. Start with a walk by the lower lake.","ja":"天山山脈のトウヒ林に囲まれた湖。まずは下コルサイ湖畔の散策から。"}'::jsonb, '{"ru":"Связь может быть нестабильной. Сохраните карту и маршрут до выезда из Алматы.","kk":"Байланыс тұрақсыз болуы мүмкін. Алматыдан шықпай тұрып карта мен бағытты сақтаңыз.","en":"Reception can be unreliable. Save the map and itinerary before leaving Almaty.","ja":"電波が不安定な場合があります。アルマトイ出発前に地図と旅程を保存しましょう。"}'::jsonb, 'Lower Kolsai Lake Saty Kazakhstan', 'https://kazakhstan.travel/en/news/things-to-do-in-almaty-region', true, null, null, 1),
  ('shymbulak', 'almaty', 'nature', 'mountains', 240, 8000, '{"ru":"Шымбулак","kk":"Шымбұлақ","en":"Shymbulak","ja":"シムブラク"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"Малоалматинское ущелье, подъём от Медеу","kk":"Кіші Алматы шатқалы, Медеуден көтерілу","en":"Little Almaty Gorge, lift from Medeu","ja":"小アルマトイ渓谷、メデウからロープウェイ"}'::jsonb, '{"ru":"Поднимитесь по канатной дороге от Медеу за панорамой Заилийского Алатау.","kk":"Іле Алатауының көрінісі үшін Медеуден аспалы жолмен көтеріліңіз.","en":"Ride the gondola from Medeu for views over the Trans-Ili Alatau.","ja":"メデウからゴンドラに乗って、トランスイリ・アラタウの山並みへ。"}'::jsonb, '{"ru":"Перед поездкой проверьте погоду и работу канатной дороги на сайте курорта.","kk":"Барар алдында курорт сайтынан ауа райы мен аспалы жолдың жұмысын тексеріңіз.","en":"Check the resort website for weather and lift operations before you go.","ja":"出発前にリゾートの公式サイトで天気とリフトの運行状況を確認してください。"}'::jsonb, 'Shymbulak Mountain Resort Almaty', 'https://shymbulak.com/', true, null, null, 2),
  ('ramen77', 'almaty', 'food', 'center', 75, 5000, '{"ru":"Ramen 77","kk":"Ramen 77","en":"Ramen 77","ja":"Ramen 77"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"ул. Кабанбай батыра, 77","kk":"Қабанбай батыр көшесі, 77","en":"77 Kabanbay Batyr Street","ja":"カバンバイ・バトゥル通り77番"}'::jsonb, '{"ru":"Японское кафе в центре Алматы. Можно зайти на рамен и закуски после прогулки.","kk":"Алматы орталығындағы жапон кафесі. Серуеннен кейін рамен мен тіскебасарға соғыңыз.","en":"A Japanese café in central Almaty, handy for ramen and snacks after a walk.","ja":"アルマトイ中心部の日本食カフェ。散策のあとにラーメンや軽食を。"}'::jsonb, '{"ru":"Рядом парк Панфилова: удобно объединить обед и прогулку.","kk":"Панфилов саябағы жақын: түскі ас пен серуенді бірге жоспарлауға болады.","en":"Pair it with a visit to nearby Panfilov Park.","ja":"近くのパンフィロフ公園の散策と組み合わせやすい場所です。"}'::jsonb, 'Ramen 77 Kabanbay Batyr 77 Almaty', 'https://yandex.com/maps/org/ramen77/234938320959/', true, 690, 290, 3),
  ('bazaar', 'almaty', 'food', 'center', 60, 1000, '{"ru":"Зелёный базар","kk":"Көк базар","en":"Green Bazaar","ja":"グリーン・バザール"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"ул. Жибек Жолы, 53","kk":"Жібек жолы көшесі, 53","en":"53 Zhibek Zholy Street","ja":"ジベク・ジョリ通り53番"}'::jsonb, '{"ru":"Городской рынок с сухофруктами, специями и местными продуктами.","kk":"Кептірілген жеміс, дәмдеуіштер және жергілікті өнімдер сатылатын қалалық базар.","en":"The city''s market for dried fruits, spices and local produce.","ja":"ドライフルーツ、香辛料、地元の食材がそろう市内の市場。"}'::jsonb, '{"ru":"Можно совместить с прогулкой по парку Панфилова в тот же день.","kk":"Осы күні Панфилов саябағына да баруға болады.","en":"Combine it with a walk through Panfilov Park on the same day.","ja":"同じ日にパンフィロフ公園の散策も楽しめます。"}'::jsonb, 'Green Bazaar Zhibek Zholy Almaty', 'https://kazakhstan.travel/en/regions/almaty', true, 720, 165, 4),
  ('cathedral', 'almaty', 'culture', 'center', 50, 0, '{"ru":"Вознесенский собор","kk":"Вознесенск кафедралды соборы","en":"Ascension Cathedral","ja":"昇天大聖堂"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"Парк 28 гвардейцев-панфиловцев","kk":"28 гвардияшы-панфиловшылар саябағы","en":"Park of 28 Panfilov Guardsmen","ja":"28人のパンフィロフ戦士公園"}'::jsonb, '{"ru":"Деревянный собор с цветными куполами в тенистом парке в центре города.","kk":"Қала орталығындағы көлеңкелі саябақта түрлі түсті күмбездері бар ағаш собор.","en":"A wooden cathedral with colourful domes in a leafy city-centre park.","ja":"市内中心部の緑豊かな公園にある、色鮮やかなドームの木造聖堂。"}'::jsonb, '{"ru":"Оставьте время на прогулку по парку и проверьте условия посещения внутри.","kk":"Саябақта серуендеуге уақыт қалдырып, ішке кіру шарттарын тексеріңіз.","en":"Leave time for the park and check visitor rules before entering the cathedral.","ja":"公園の散策時間も取り、聖堂内に入る前に見学ルールを確認しましょう。"}'::jsonb, 'Ascension Cathedral Panfilov Park Almaty', 'https://kazakhstan.travel/en/regions/almaty', true, 750, 240, 5),
  ('kok-tobe', 'almaty', 'city', 'hill', 120, 4500, '{"ru":"Кок-Тобе","kk":"Көктөбе","en":"Kok Tobe","ja":"コクトベ"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"Гора Кок-Тобе, станция канатной дороги на пр. Достык","kk":"Көктөбе, Достық даңғылындағы аспалы жол бекеті","en":"Kok Tobe hill, cable car station on Dostyk Avenue","ja":"コクトベの丘、ドスティク大通りのロープウェイ駅"}'::jsonb, '{"ru":"Вид на Алматы и горы со смотровых площадок на холме.","kk":"Төбедегі көрініс алаңдарынан Алматы мен таулар көрінеді.","en":"Look out over Almaty and the mountains from the hilltop viewpoints.","ja":"丘の上の展望台からアルマトイの街と山並みを一望できます。"}'::jsonb, '{"ru":"В ясную погоду запланируйте прогулку ближе к закату.","kk":"Ашық күнде күн батар алдында серуендеңіз.","en":"On a clear day, plan your visit for late afternoon.","ja":"晴れた日なら、夕方の訪問がおすすめです。"}'::jsonb, 'Kok Tobe Cable Car Almaty Dostyk', 'https://kazakhstan.travel/en/regions/almaty', true, 935, 465, 6),
  ('rodem', 'almaty', 'food', 'center', 75, 4800, '{"ru":"Rodem","kk":"Rodem","en":"Rodem","ja":"Rodem"}'::jsonb, '{"ru":"Алматы","kk":"Алматы","en":"Almaty","ja":"アルマトイ"}'::jsonb, '{"ru":"пр. Абылай хана, 64","kk":"Абылай хан даңғылы, 64","en":"64 Abylai Khan Avenue","ja":"アブライ・ハン大通り64番"}'::jsonb, '{"ru":"Корейское кафе рядом с пешеходной частью Жибек Жолы.","kk":"Жібек жолының жаяу жүргінші бөлігіне жақын корей кафесі.","en":"A Korean café near the pedestrian section of Zhibek Zholy.","ja":"ジベク・ジョリの歩行者エリア近くにある韓国料理カフェ。"}'::jsonb, '{"ru":"Удобная остановка на обед во время прогулки по центру.","kk":"Қала орталығында серуендегенде түскі асқа ыңғайлы аялдама.","en":"A convenient lunch stop on a walk through the centre.","ja":"中心街の散策中にランチで立ち寄りやすい場所です。"}'::jsonb, 'Rodem Abylai Khan 64 Almaty', 'https://wikicity.kz/en/biz/rodem-almaty', true, 545, 235, 7),
